package com.luci.pianoroom;
import java.io.*;import java.util.*;
public final class PerformanceFeaturesTest {
 static void check(boolean b,String s){if(!b)throw new AssertionError(s);}
 public static void main(String[]args)throws Exception {
  Scene s=new Scene();s.effects[0].resonance=15;s.effects[2].delay=30;s.effects[2].low=-3;s.xyEnabled=true;s.xyX=.3f;s.xyMode=2;Scene decoded=Scene.decode(s.encode());check(decoded.effects[0].resonance==15&&decoded.effects[2].delay==30&&decoded.effects[2].low==-3&&decoded.xyEnabled&&decoded.xyX==.3f&&decoded.xyMode==2,"scene FX and XY");byte[] old=Base64.getDecoder().decode(s.encode());old=Arrays.copyOf(old,old.length-481);old[3]=2;Scene legacy=Scene.decode(Base64.getEncoder().encodeToString(old));check(legacy.effects[0].resonance==0&&!legacy.xyEnabled&&legacy.gains[0]==s.gains[0],"v2 migration");old=Arrays.copyOf(old,old.length-12);old[3]=1;legacy=Scene.decode(Base64.getEncoder().encodeToString(old));check(legacy.solo==-1&&legacy.effects[0].resonance==0,"v1 migration");s.effects[0].feedback=99;try{Scene.decode(s.encode());throw new AssertionError("invalid FX");}catch(IOException expected){}
  List<MidiTape.Event> events=Arrays.asList(new MidiTape.Event(0,0xB0,64,127),new MidiTape.Event(100000,0x90,60,70),new MidiTape.Event(200000,0x90,60,80),new MidiTape.Event(300000,0x80,60,0),new MidiTape.Event(400000,0x80,60,0),new MidiTape.Event(500000,0xB0,64,0));MidiEdit edit=new MidiEdit(events);check(edit.notes.size()==2&&edit.notes.get(0).end==300000&&edit.notes.get(1).end==400000,"FIFO overlap");edit.notes.get(0).key=62;edit.notes.get(0).velocity=101;edit.notes.get(1).deleted=true;List<MidiTape.Event> exported=edit.export();check(exported.size()==4&&exported.get(0).a==64&&exported.get(1).a==62&&exported.get(1).b==101&&exported.get(2).a==62&&exported.get(3).a==64,"edit preserves pedal, matched release, delete pair");check(new MidiEdit(edit.original()).notes.get(0).key==60,"undo restores original");
  MidiHistory history=new MidiHistory();history.enable(true);history.add(176,64,127);history.add(144,60,77);history.add(128,60,0);Thread.sleep(3);long end=System.nanoTime()/1000;List<MidiTape.Event> retro=history.snapshot(end,1000);boolean on=false,off=false,pedal=false;for(MidiTape.Event e:retro){if(e.micros==0&&e.status==144&&e.a==60&&e.b==77)on=true;if(e.micros==0&&e.status==128&&e.a==60)off=true;if(e.micros==0&&e.status==176&&e.a==64&&e.b==127)pedal=true;}check(on&&off&&pedal,"sustained note reconstruction at history start");history.add(176,64,0);Thread.sleep(3);retro=history.snapshot(System.nanoTime()/1000,1000);for(MidiTape.Event e:retro)check((e.status&240)!=144,"pedal off clears reconstruction");history.enable(false);check(history.snapshot(System.nanoTime()/1000,1000).size()==32,"disable clears state");System.out.println("Performance features: scene v4 FX/XY, MIDI editing FIFO/controller preservation and retrospective pedal state passed");
 }
}
